module grid_generator(\n    input clk,\n    input rst_n,\n    input start,\n    input [8:0] A,\n    input [8:0] B,\n    output reg [7:0] char_out,\n    output reg valid_out,\n    output reg done\n);\n\n    // State declarations (explicit widths)\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] HEAD = 2'd1;\n    localparam [1:0] GRID = 2'd2;\n    localparam [1:0] DONE_ST = 2'd3;\n    \n    reg [1:0] state, next_state;\n    reg [3:0] header_index;\n    reg [9:0] row;\n    reg [9:0] col;\n    reg [8:0] A_reg;\n    reg [8:0] B_reg;\n\n    // Character calculation function\n    function automatic [7:0] calc_char;\n        input [9:0] i;\n        input [9:0] j;\n        input [8:0] A_val;\n        input [8:0] B_val;\n        reg [15:0] idx;\n        begin\n            if (i < 10'd50) begin\n                if (i[0] && j[0]) begin\n                    idx = ((i-1) >> 1) * 50 + ((j-1) >> 1);\n                    calc_char = (idx < (B_val - 1)) ? "#" : ".";\n                end else begin\n                    calc_char = ".";\n                end\n            end else begin\n                if ((i >= 10'd51) && (i <= 10'd97) && i[0] && j[0]) begin\n                    idx = ((i-51) >> 1) * 50 + ((j-1) >> 1);\n                    calc_char = (idx < (A_val - 1)) ? "." : "#";\n                end else begin\n                    calc_char = "#";\n                end\n            end\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize ALL registers\n            state <= IDLE;\n            char_out <= 8'd0;\n            valid_out <= 1'b0;\n            done <= 1'b0;\n            header_index <= 4'd0;\n            row <= 10'd0;\n            col <= 10'd0;\n            A_reg <= 9'd0;\n            B_reg <= 9'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    valid_out <= 1'b0;\n                    if (start) begin\n                        A_reg <= A;\n                        B_reg <= B;\n                        state <= HEAD;\n                        header_index <= 4'd0;\n                    end\n                end\n                \n                HEAD: begin\n                    valid_out <= 1'b1;\n                    case (header_index)\n                        4'd0: char_out <= "1";\n                        4'd1: char_out <= "0";\n                        4'd2: char_out <= "0";\n                        4'd3: char_out <= " ";\n                        4'd4: char_out <= "1";\n                        4'd5: char_out <= "0";\n                        4'd6: char_out <= "0";\n                        4'd7: char_out <= "\n";\n                        default: char_out <= 8'd0;\n                    endcase\n                    \n                    if (header_index < 4'd7) begin\n                        header_index <= header_index + 4'd1;\n                    end else begin\n                        state <= GRID;\n                        row <= 10'd0;\n                        col <= 10'd0;\n                    end\n                end\n                \n                GRID: begin\n                    valid_out <= 1'b1;\n                    if (col < 10'd99) begin\n                        char_out <= calc_char(row, col, A_reg, B_reg);\n                        col <= col + 10'd1;\n                    end else begin\n                        // End of row - output newline\n                        char_out <= "\n";\n                        col <= 10'd0;\n                        if (row < 10'd99) begin\n                            row <= row + 10'd1;\n                        end else begin\n                            state <= DONE_ST;\n                        end\n                    end\n                end\n                \n                DONE_ST: begin\n                    done <= 1'b1;\n                    valid_out <= 1'b0;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule\n